using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> typeInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>() => Type = {typeInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---
// With the default (reflection-based) resolver, Person resolves fine:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? personInfo))
    Console.WriteLine($"TryGetTypeInfo<Person>() => found ({personInfo!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<Person>() => not available");

// With an empty custom resolver, nothing resolves – no exception thrown:
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) => throw new NotSupportedException() }
    }
};

if (empty.TryGetTypeInfo<Person>(out _))
    Console.WriteLine("TryGetTypeInfo<Person>(empty) => found");
else
    Console.WriteLine("TryGetTypeInfo<Person>(empty) => not available (expected)");

public record Person(string Name, int Age);

